/*
 * A047614  Numbers that are congruent to {0, 1, 2, 4, 5} mod 8.
 * https://oeis.org/A047614
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the nth nonnegative integer congruent to * {0, 1, 2, 4,
 *            5} modulo 8. The sequence is generated by * a(n) = ⌊(n-1)/5⌋·8 +
 *            {0,1,2,4,5}_{(n-1) mod 5}
 * Range:     u8 n <= 57, u16 n <= 57, u32 n <= 57, u64 n <= 57, u128 n <= 57,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* n is guaranteed >= 1.  All arithmetic below uses only
     * integer operations allowed by the problem statement. */

    /* Off‑by‑one: convert 1‑based index to 0‑based step. */
    idx_t step = n - 1;

    /* Determine how many full 5‑element blocks have been passed. */
    idx_t block = step / 5;

    /* Find position within the current block. */
    idx_t pos = step % 5;

    /* Residues that are allowed modulo 8, in ascending order. */
    static const seq_t residues[5] = {0, 1, 2, 4, 5};

    /* Compute the value: block * 8 + allowed residue. */
    seq_t value = (seq_t)block * 8 + residues[pos];

    return value;
}
